\begin{tabular}{cccc}
\toprule
\# & Sky & AirTemp & EnjoySport \\
\midrule
1 & Sunny & Warm & Yes \\
2 & Sunny & Cold & No \\
3 & Rainy & Warm & Yes \\
\bottomrule
\end{tabular}
\end{center}
Trace the Candidate Elimination Algorithm on this dataset.

\textbf{Solution:}
\[
S_0 = \{\langle \varnothing,\varnothing \rangle\}, \qquad G_0 = \{\langle ?,? \rangle\}
\]
\textbf{Example 1 (Sunny, Warm, Yes) --- positive:} generalize $S_0$ minimally to cover it.
\[
S_1 = \{\langle \text{Sunny},\text{Warm} \rangle\}, \qquad G_1 = \{\langle ?,? \rangle\} \ \text{(already accepts it, unchanged)}
\]
\textbf{Example 2 (Sunny, Cold, No) --- negative:} $S_1$ already rejects it (unchanged). Specialize $G_1$ minimally to exclude it, keeping every result more general than $S_1$.
\begin{align*}
\text{Try Sky} &\to \text{Rainy}: \langle \text{Rainy},? \rangle \ \text{---rejects positive example 1, discard} \\
\text{Try AirTemp} &\to \text{Warm}: \langle ?,\text{Warm} \rangle \ \text{---accepts positive example 1, keep}
\end{align*}
\[
S_2 = \{\langle \text{Sunny},\text{Warm} \rangle\}, \qquad G_2 = \{\langle ?,\text{Warm} \rangle\}
\]
\textbf{Example 3 (Rainy, Warm, Yes) --- positive:} $S_2$ does not accept it (Sky mismatch); generalize minimally.
\[
S_3 = \{\langle ?,\text{Warm} \rangle\}
\]
$G_2$ already accepts $(\text{Rainy},\text{Warm})$ (AirTemp matches Warm), so it is unchanged: $G_3=\{\langle ?,\text{Warm} \rangle\}$.
\boxed{S_3 = G_3 = \{\langle ?,\text{Warm} \rangle\}}
Since $S$ and $G$ have converged to a single, identical hypothesis, the version space contains exactly one hypothesis --- the target concept has been fully learned.

\begin{center}
\begin{tabular}{cccc}
\toprule
\# & Sky & Wind & Target \\
\midrule
1 & Sunny & Weak & Yes \\
2 & Rainy & Strong & No \\
3 & Sunny & Strong & Yes \\
\bottomrule
\end{tabular}
\end{center}
Trace the Candidate Elimination Algorithm on this dataset.

\textbf{Solution:}
\[
S_0 = \{\langle \varnothing,\varnothing \rangle\}, \qquad G_0 = \{\langle ?,? \rangle\}
\]
\textbf{Example 1 (Sunny, Weak, Yes) --- positive:}
\[
S_1 = \{\langle \text{Sunny},\text{Weak} \rangle\}, \qquad G_1 = \{\langle ?,? \rangle\}
\]
\textbf{Example 2 (Rainy, Strong, No) --- negative:} specialize $G_1$ minimally; both single-attribute specializations remain consistent with the positive example seen so far.
\begin{align*}
\text{Sky} &\to \text{Sunny}: \langle \text{Sunny},? \rangle \ \text{---accepts example 1, keep} \\
\text{Wind} &\to \text{Weak}: \langle ?,\text{Weak} \rangle \ \text{---accepts example 1, keep}
\end{align*}
\[
S_2 = \{\langle \text{Sunny},\text{Weak} \rangle\}, \qquad G_2 = \{\langle \text{Sunny},? \rangle,\ \langle ?,\text{Weak} \rangle\}
\]
\textbf{Example 3 (Sunny, Strong, Yes) --- positive:} $S_2$ does not accept it (Wind mismatch); generalize minimally.
\[
S_3 = \{\langle \text{Sunny},? \rangle\}
\]
Check each member of $G_2$ against this positive example:
\begin{align*}
\langle \text{Sunny},? \rangle &: \text{accepts (Sunny,Strong)} \Rightarrow \text{keep} \\
\langle ?,\text{Weak} \rangle &: \text{Wind=Weak} \ne \text{Strong} \Rightarrow \text{rejects positive} \Rightarrow \text{discard}
\end{align*}
\[
G_3 = \{\langle \text{Sunny},? \rangle\}
\]
\boxed{S_3 = G_3 = \{\langle \text{Sunny},? \rangle\}}
The negative example first caused $G$ to \textbf{branch} into two candidate hypotheses; the next positive example then eliminated the branch inconsistent with it, and $S$ and $G$ converged together.

